from typing import Any, Dict


class ManagedMetricsRequest:
    def __init__(self, metric_name: str, metric_value: float, timestamp: int):
        self.metric_name = metric_name
        self.metric_value = metric_value
        self.timestamp = timestamp

    def to_dict(self) -> Dict[str, Any]:
        return {
            'metric_name': self.metric_name,
            'metric_value': self.metric_value,
            'timestamp': self.timestamp,
        }


class ManagedMetricsResponse:
    def __init__(self, status: str, message: str):
        self.status = status
        self.message = message

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        return cls(data['status'], data['message'])


def normalize_metric_name(metric_name: str) -> str:
    return metric_name.lower().replace(' ', '_')


def normalize_metric_value(metric_value: float) -> float:
    return round(metric_value, 2)

import boto3

def configure_cloudwatch(region_name):
    return boto3.client('cloudwatch', region_name=region_name)

def put_metric_data(client, namespace, metric_data):
    response = client.put_metric_data(
        Namespace=namespace,
        MetricData=metric_data
    )
    return response

def get_metric_statistics(client, namespace, metric_name, start_time, end_time, period, statistics, dimensions=None):
    response = client.get_metric_statistics(
        Namespace=namespace,
        MetricName=metric_name,
        StartTime=start_time,
        EndTime=end_time,
        Period=period,
        Statistics=statistics,
        Dimensions=dimensions
    )
    return response

